package com.worstcase.app

import com.worstcase.app.core.DailyPicker
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.BufferedReader

/**
 * The TypeScript picker and the Kotlin picker are independent implementations of
 * the same contract; both must reproduce test/golden/daily-picker.csv exactly.
 * The CSV is generated by scripts/generate-golden.ts and copied to resources.
 */
class DailyPickerTest {

    private val pool = (1..40).toList()

    @Test
    fun `reproduces the TypeScript golden days`() {
        val stream = javaClass.classLoader?.getResourceAsStream("daily-picker.csv")
            ?: error("daily-picker.csv missing from test resources")
        var checked = 0
        stream.bufferedReader().use(BufferedReader::readLines).drop(1).forEach { line ->
            if (line.isBlank()) return@forEach
            val parts = line.split(",")
            val day = parts[0].toLong()
            val id = parts[1].toInt()
            assertEquals("day $day", id.toLong(), DailyPicker.pick(pool, GOLDEN_SEED, day).toLong())
            checked += 1
        }
        assertEquals(60, checked)
    }

    @Test
    fun `never repeats within a cycle and never bridges cycles`() {
        val first = (0 until pool.size).map { DailyPicker.pick(pool, GOLDEN_SEED, it.toLong()) }
        assertEquals(pool.size, first.toSet().size)

        val boundary = pool.size.toLong()
        val lastOfCycle = DailyPicker.pick(pool, GOLDEN_SEED, boundary - 1)
        val firstOfNext = DailyPicker.pick(pool, GOLDEN_SEED, boundary)
        assertTrue("cycle boundary repeated $lastOfCycle", lastOfCycle != firstOfNext)
    }

    @Test
    fun `same day always picks the same entry`() {
        val day = 20_700L
        assertEquals(DailyPicker.pick(pool, GOLDEN_SEED, day), DailyPicker.pick(pool, GOLDEN_SEED, day))
    }

    companion object {
        private const val GOLDEN_SEED = 0x5eed1234
    }
}